+
+// exampleContradictionLine is the refusal line of one contradicting example row. When expected and
+// derived both parse as objects it names the top-level fields that differ, then gives both values;
+// otherwise it gives the two values. The checker's why, on one line, is the last segment, so the
+// cut of a long refusal line keeps it.
+func exampleContradictionLine(scenario, expected, derived, why string) string {
+	tail := ""
+	if why = strings.Join(strings.Fields(why), " "); why != "" {
+		tail = " | why: " + why
+	}
+	a, okA := exampleValue(expected)
+	b, okB := exampleValue(derived)
+	x, objA := a.(map[string]any)
+	y, objB := b.(map[string]any)
+	if !okA || !okB || !objA || !objB {
+		return scenario + ": expected " + expected + ", rules give " + derived + tail
+	}
+	var names []string
+	for k, v := range x {
+		if w, ok := y[k]; !ok || !exampleEqual(v, w) {
+			names = append(names, k)
+		}
+	}
+	for k := range y {
+		if _, ok := x[k]; !ok {
+			names = append(names, k)
+		}
+	}
+	slices.Sort(names)
+	return scenario + ": differs in " + strings.Join(names, ", ") + " | expected " + expected + " | rules give " + derived + tail
+}

